(() => {
 const encoder=new TextEncoder(),decoder=new TextDecoder();let enabled=false,key,secret,currentRoom,currentMember,currentToken,pendingSecret;
 const to64=bytes=>btoa(String.fromCharCode(...bytes)),from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
 const importKey=raw=>crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt']);
 async function init(){const res=await fetch('/api/config');if(!res.ok)throw Error('Não foi possível verificar a proteção da sala. Atualize a página.');const config=await res.json();enabled=!!config.encrypted;return config}
 async function create(){if(enabled)pendingSecret=to64(crypto.getRandomValues(new Uint8Array(32)))}
 async function activate(roomId,memberId,token){if(!enabled)return;const saved=await window.durableQueue.access(roomId);const fragment=new URLSearchParams(location.hash.slice(1)).get('k');secret=pendingSecret||fragment||saved?.secret;if(!secret||from64(secret).length!==32)throw Error('Abra o convite completo com a chave privada ou importe seu arquivo de acesso.');key=await importKey(from64(secret));pendingSecret=null;currentRoom=roomId;currentMember=memberId||saved?.memberId;currentToken=token||saved?.token;if(currentMember&&currentToken)await window.durableQueue.saveAccess({roomId,secret,memberId:currentMember,token:currentToken});}
 async function encode(body){if(!enabled)return body;if(!key||!currentMember)throw Error('A chave privada da sala não está disponível.');const iv=crypto.getRandomValues(new Uint8Array(12));const content={text:body.text,rawText:body.rawText??body.text,kind:body.kind,punctuation:'browser'};const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:encoder.encode(currentRoom+':'+currentMember+':'+body.clientId)},key,encoder.encode(JSON.stringify(content)));return {clientId:body.clientId,capturedAt:body.capturedAt,payload:{v:1,algorithm:'AES-GCM',iv:to64(iv),ciphertext:to64(new Uint8Array(ciphertext))}}}
 async function decode(record){if(!record?.payload)return record;if(!key)throw Error('Falta a chave privada para abrir esta transcrição.');try{const data=await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(record.payload.iv),additionalData:encoder.encode(currentRoom+':'+record.memberId+':'+record.clientId)},key,from64(record.payload.ciphertext));const content=JSON.parse(decoder.decode(data));if(typeof content.text!=='string'||content.text.length>8000)throw Error();return {...record,text:content.text,rawText:content.rawText,kind:content.kind,punctuation:content.punctuation}}catch{throw Error('Não foi possível abrir um trecho. A chave pode estar incorreta ou os dados foram alterados.')}}
 async function response(data){if(data.payload)return decode(data);if(data.records)data.records=await Promise.all(data.records.map(decode));if(data.transcripts)data.transcripts=await Promise.all(data.transcripts.map(decode));if(data.state?.transcripts)data.state.transcripts=await Promise.all(data.state.transcripts.map(decode));return data}
 const invitation=base=>enabled?base+'#k='+encodeURIComponent(secret):base;
 async function savedToken(roomId){if(!enabled)return null;return (await window.durableQueue.access(roomId))?.token}
 const save=document.createElement('button');save.id='savePrivateAccess';save.textContent='Guardar acesso privado da aula';save.hidden=true;document.querySelector('.livebox').append(save);
 const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Guardar acesso à aula</h2><p>O arquivo inclui sua chave e seu acesso à transcrição. Proteja-o com uma senha. Sem a chave ou esse arquivo, o servidor não consegue recuperar o conteúdo para você.</p><label>Senha do arquivo<input id="backupPassword" type="password" minlength="10" autocomplete="new-password"></label><p id="backupStatus" role="status"></p><button id="saveBackup" class="primary">Baixar arquivo protegido</button><button id="cancelBackup">Cancelar</button>';document.body.append(dialog);
 async function backupKey(password,salt){const material=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
 save.onclick=()=>dialog.showModal();document.getElementById('cancelBackup').onclick=()=>dialog.close();
 document.getElementById('saveBackup').onclick=async()=>{const password=document.getElementById('backupPassword').value;if(password.length<10){document.getElementById('backupStatus').textContent='Use uma senha de pelo menos 10 caracteres.';return}try{const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),bk=await backupKey(password,salt);const payload=await crypto.subtle.encrypt({name:'AES-GCM',iv},bk,encoder.encode(JSON.stringify({roomId:currentRoom,secret,memberId:currentMember,token:currentToken})));const file={format:'aula-global-backup-v1',salt:to64(salt),iv:to64(iv),ciphertext:to64(new Uint8Array(payload))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(file)],{type:'application/json'}));a.download='aula-global-acesso-protegido.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.getElementById('backupPassword').value='';dialog.close()}catch{document.getElementById('backupStatus').textContent='Não foi possível criar o arquivo protegido.'}};
 window.roomSecurity={init,create,activate,encode,response,invitation,savedToken,enabled:()=>enabled,showBackup(){save.hidden=!enabled}};
})();
